package com.silverguardian.prototype.data.dao;
import android.content.ContentValues;import android.database.Cursor;import com.silverguardian.prototype.data.ElderlyDbHelper;import com.silverguardian.prototype.models.AlbumPhoto;import java.util.*;
public class AlbumDao{
 private final ElderlyDbHelper h;public AlbumDao(ElderlyDbHelper h){this.h=h;}
 public List<AlbumPhoto> readAll(int uid){List<AlbumPhoto>r=new ArrayList<>();Cursor c=h.getReadableDatabase().rawQuery("SELECT id,url,COALESCE(public_uri,''),title,description,category,uploaded_by,favorite,scene_tag,family_message FROM album_photos WHERE user_id=? ORDER BY id DESC",new String[]{String.valueOf(uid)});while(c.moveToNext())r.add(new AlbumPhoto(c.getInt(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5),c.getString(6),c.getInt(7)==1,c.getString(8),c.getString(9)));c.close();return r;}
 public int add(int uid,String privatePath,String publicUri,String title,String category,String message){ContentValues v=new ContentValues();v.put("user_id",uid);v.put("url",privatePath);v.put("public_uri",publicUri);v.put("title",title);v.put("description","家属上传的照片");v.put("category",category);v.put("uploaded_by","家属");v.put("scene_tag",category);v.put("family_message",message);return(int)h.getWritableDatabase().insertOrThrow("album_photos",null,v);}
 public void delete(int id){h.getWritableDatabase().delete("album_photos","id=?",new String[]{String.valueOf(id)});}
 public void setFavorite(int id,boolean favorite){ContentValues v=new ContentValues();v.put("favorite",favorite?1:0);h.getWritableDatabase().update("album_photos",v,"id=?",new String[]{String.valueOf(id)});}
}